pub trait Preconditioner: Send + Sync {
    fn dimension(&self) -> usize;
    fn apply(&self, x: &[f64], y: &mut [f64]) -> CoreResult<()>;
    /// n-vector equivalents solved by one apply (s for stage-block preconditioners).
    fn application_vectors(&self) -> u64 { 1 }
}
pub fn apply_preconditioner(p: &dyn Preconditioner, x: &[f64], y: &mut [f64],
                            c: &mut WorkCounters) -> CoreResult<()> {
    p.apply(x, y)?;
    c.preconditioner_apps += 1;                               // solver-level
    c.preconditioner_vectors += p.application_vectors();      // vector-level
    Ok(())
}
