impl NewtonConfig {
    /// Tier-A stopping rule: converge the nonlinear solve only as far as the
    /// outer error test can see.
    pub fn scaled_to_outer(outer_atol: f64, outer_rtol: f64) -> Self {
        let kappa = (10.0 * f64::EPSILON / outer_rtol).max(0.03_f64.min(outer_rtol.sqrt()));
        Self { atol: kappa * outer_atol, rtol: kappa * outer_rtol, ..Self::default() }
    }
}

pub struct NewtonLinearCache {            // owned by the stepper, survives across steps
    factor: Option<LuFactorization>,
    h_gamma: f64,
    jacobian_age_steps: usize,
}
// refactor iff |h_gamma/cached - 1| > 0.2, or contraction rate > 0.9, or age > 20;
// counters.direct_factorizations += 1 only when a factorization really happens.

struct EstimatorLuCache { h_bits: u64, jacobian_token: u64, factor: LuFactorization }

fn estimator_factor<'c>(cache: &'c mut Option<EstimatorLuCache>, mass: &DenseMatrix,
    jacobian: &DenseMatrix, token: u64, h: f64, mu: f64, counters: &mut WorkCounters,
) -> CoreResult<&'c LuFactorization> {
    let hit = cache.as_ref()
        .is_some_and(|c| c.h_bits == h.to_bits() && c.jacobian_token == token);
    if !hit {
        let op = mass.scale(mu / h).combine(jacobian, -1.0)?;
        counters.estimator_factorizations += 1;   // reported separately from stage LUs
        *cache = Some(EstimatorLuCache { h_bits: h.to_bits(), jacobian_token: token,
                                         factor: LuFactorization::new(&op)? });
    }
    Ok(&cache.as_ref().expect("filled above").factor)
}

pub enum WallVerdict { Promote, Block, Inconclusive, NotEvaluated }

/// log_ratios[case][pair] = ln(reference_seconds / candidate_seconds)
pub fn bootstrap_speedup_ci(log_ratios: &[Vec<f64>], seed: u64, draws: usize) -> (f64, f64) {
    let mut rng = Pcg64Mcg::seed_from_u64(seed);
    let mut stats = Vec::with_capacity(draws);
    for _ in 0..draws {
        let mut medians = Vec::with_capacity(log_ratios.len());
        for _ in 0..log_ratios.len() {                       // resample cases
            let case = &log_ratios[rng.random_range(0..log_ratios.len())];
            let mut draw: Vec<f64> = (0..case.len())         // resample pairs
                .map(|_| case[rng.random_range(0..case.len())]).collect();
            draw.sort_by(f64::total_cmp);
            medians.push(quantile_sorted(&draw, 0.5));
        }
        medians.sort_by(f64::total_cmp);
        stats.push(quantile_sorted(&medians, 0.5));
    }
    stats.sort_by(f64::total_cmp);
    (quantile_sorted(&stats, 0.025).exp(), quantile_sorted(&stats, 0.975).exp())
}
pub fn decide(ci: (f64, f64), threshold: f64) -> WallVerdict {
    if ci.0 >= threshold { WallVerdict::Promote }
    else if ci.1 < threshold { WallVerdict::Block } else { WallVerdict::Inconclusive }
}
